  assign b3_0 = b[3];             // primary input
  assign b4_0 = 1'b0;             // ancilla, constant 0

  peres_gate    u1 (.a(a0_0), .b(b0_0), .c(c1_0), .p(a0_1), .q(b0_1), .r(c1_1));
  peres_gate    u2 (.a(a1_0), .b(b1_0), .c(c2_0), .p(a1_1), .q(b1_1), .r(c2_1));
  toffoli_gate  u3 (.a(c1_1), .b(b1_1), .c(c2_1), .p(c1_2), .q(b1_2), .r(c2_2));
  peres_gate    u4 (.a(a2_0), .b(b2_0), .c(c3_0), .p(a2_1), .q(b2_1), .r(c3_1));
