  input  [3:0] a,
  input  [3:0] b,
  output [3:0] sum,
  output        cout,
  output        clean
);
  wire a0_0, b0_0, a1_0, b1_0, a2_0, b2_0, a3_0, b3_0;
  wire z0_0, z1_0, z2_0, z3_0, z4_0, p1_1_0, a0_1, b0_1;
  wire z1_1, a1_1, b1_1, z2_1, a2_1, b2_1, z3_1, a3_1;
